package com.collaborativecanvas.server.service;
import com.collaborativecanvas.shared.dto.*;import com.collaborativecanvas.shared.enums.*;import org.junit.jupiter.api.Test;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
class CanvasDocumentReplayTest {private DrawingOperationMessage op(DrawingOperationType t,long seq,String stroke){return new DrawingOperationMessage(UUID.randomUUID(),"ABCDEFGH","p",t,stroke,.5,.5,"#1E88E5",6,t.name().startsWith("ERASE"),seq,null,null);}@Test void clearIsOrderedAndRemovesEarlierStrokes(){CanvasStateService service=new CanvasStateService(null,null,null,new com.fasterxml.jackson.databind.ObjectMapper());var doc=service.apply(CanvasDocument.empty(),List.of(op(DrawingOperationType.DRAW_START,1,"a"),op(DrawingOperationType.CLEAR_CANVAS,2,null),op(DrawingOperationType.DRAW_START,3,"b")));assertEquals(List.of("b"),doc.strokes().stream().map(CanvasStroke::strokeId).toList());}}
